#include "../src/rendering/text/document_html_capture.h"
#include <fstream>
#include <iostream>
using namespace aether::rendering;
std::string read(const char*p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error(p);return {(std::istreambuf_iterator<char>(f)),{}};}
int main(int argc,char**argv){if(argc!=3)return 2;auto raw=read(argv[1]);auto load=[](const char*p){auto b=read(p);return std::make_shared<const text::FontSource>(std::vector<uint8_t>(b.begin(),b.end()),p);};text::DocumentFontCatalog fonts{load("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"),load("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf")};int failures=0;for(unsigned w:{640,240}){auto result=capture_document_html(raw,fonts,w,480);if(auto*e=std::get_if<SelectedCaptureFailure>(&result)){std::cout<<"width="<<w<<" FAIL code="<<int(e->code)<<" reason="<<e->reason<<"\n";++failures;continue;}auto frame=std::get<std::shared_ptr<const DocumentCaptureFrame>>(result);std::cout<<"width="<<w<<" frame="<<frame->frame.viewport.width<<"x"<<frame->frame.viewport.height<<" complete="<<frame->coverage_complete<<" range="<<frame->viewport.range_x<<","<<frame->viewport.range_y<<" placed="<<frame->work.paint.placed_glyphs<<" masks="<<frame->work.paint.mask_misses<<" hits="<<frame->work.paint.mask_hits<<" raster_reserved="<<frame->work.raster_reserved<<" shadows="<<frame->work.shadow_commands<<" software_work="<<frame->work.software_work<<" raster_ns="<<frame->work.raster_ns<<"\n";std::ofstream out(std::string(argv[2])+"-"+std::to_string(w)+".bgra",std::ios::binary);out.write((const char*)frame->frame.pixels.data(),frame->frame.pixels.size());for(auto&s:frame->samples)std::cout<<"sample="<<s.occurrence<<" box="<<s.logical_rect.x<<","<<s.logical_rect.y<<","<<s.logical_rect.width<<","<<s.logical_rect.height<<" baseline="<<s.logical_baseline<<" glyphs="<<s.glyphs<<"\n";}return failures?1:0;}
